using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;using System.Text.Json;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController(ApiClient api):Controller{
 private bool Guard()=>HttpContext.Session.GetString("User") is string u && JsonDocument.Parse(u).RootElement.GetProperty("role").GetString()=="Organiser";
 private IActionResult Deny()=>RedirectToAction("Login","Auth");
 public async Task<IActionResult> Index(){if(!Guard())return Deny();var r=await api.Send("GET","api/events?mine=true&includePast=true");ViewBag.Error=r.Error;var events=r.Data?.RootElement.EnumerateArray().Select(x=>x.Clone()).ToList()??new();var stats=new List<(JsonElement ev,int enrol)>();foreach(var e in events){var n=await api.Send("GET",$"api/events/{e.GetProperty("eventId").GetInt32()}/enrolments");stats.Add((e,n.Data?.RootElement.GetArrayLength()??0));}ViewBag.Stats=stats;return View(events);}
 [HttpGet] public IActionResult CreateEvent(){if(!Guard())return Deny();return View("EventForm",new EventVm());}
 [HttpPost] public async Task<IActionResult> CreateEvent(EventVm vm,IFormFile? banner){if(!Guard())return Deny();if(!ModelState.IsValid)return View("EventForm",vm);var r=await api.Send("POST","api/events",vm);if(!r.Ok){ModelState.AddModelError("",r.Error!);return View("EventForm",vm);}int id=r.Data!.RootElement.GetProperty("eventId").GetInt32();if(banner!=null&&banner.Length>0){var up=await api.Upload($"api/events/{id}/banner",banner);if(!up.Ok)TempData["Error"]="Event saved, but banner upload failed: "+up.Error;}return RedirectToAction(nameof(Manage),new{id});}
 [HttpGet] public async Task<IActionResult> EditEvent(int id){if(!Guard())return Deny();var r=await api.Send("GET",$"api/events/{id}");if(!r.Ok)return NotFound();var e=r.Data!.RootElement;return View("EventForm",new EventVm{EventId=id,EventName=e.GetProperty("eventName").GetString()!,EventDate=e.GetProperty("eventDate").GetDateTime().Date==default?DateOnly.FromDateTime(DateTime.Today):DateOnly.FromDateTime(e.GetProperty("eventDate").GetDateTime()),Location=e.GetProperty("location").GetString()!,Description=e.TryGetProperty("description",out var d)?d.GetString():null,WeatherLocationCode=e.TryGetProperty("weatherLocationCode",out var w)?w.GetString():null,EventType=e.GetProperty("eventType").GetString()!,DistanceKM=e.GetProperty("distanceKM").GetDecimal(),BannerImageUrl=e.TryGetProperty("bannerImageUrl",out var b)?b.GetString():null});}
 [HttpPost] public async Task<IActionResult> EditEvent(EventVm vm,IFormFile? banner){if(!Guard())return Deny();if(!ModelState.IsValid)return View("EventForm",vm);var r=await api.Send("PUT",$"api/events/{vm.EventId}",vm);if(!r.Ok){ModelState.AddModelError("",r.Error!);return View("EventForm",vm);}if(banner!=null&&banner.Length>0){var up=await api.Upload($"api/events/{vm.EventId}/banner",banner);if(!up.Ok)TempData["Error"]="Event updated, but banner upload failed: "+up.Error;}return RedirectToAction(nameof(Manage),new{id=vm.EventId});}
 [HttpPost] public async Task<IActionResult> DeleteEvent(int id){if(!Guard())return Deny();var r=await api.Send("DELETE",$"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Event deleted.":r.Error;return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Manage(int id){if(!Guard())return Deny();var e=await api.Send("GET",$"api/events/{id}");var c=await api.Send("GET",$"api/events/{id}/categories");var en=await api.Send("GET",$"api/events/{id}/enrolments");var re=await api.Send("GET",$"api/events/{id}/results");ViewBag.Event=e.Data?.RootElement.Clone();ViewBag.Categories=c.Data?.RootElement.Clone();ViewBag.Enrolments=en.Data?.RootElement.Clone();ViewBag.Results=re.Data?.RootElement.Clone();ViewBag.Error=e.Error??c.Error??en.Error??re.Error;return View();}
 [HttpPost] public async Task<IActionResult> AddCategory(int id,CategoryVm vm){if(!Guard())return Deny();var r=await api.Send("POST",$"api/events/{id}/categories",vm);TempData[r.Ok?"Success":"Error"]=r.Ok?"Category added.":r.Error;return RedirectToAction(nameof(Manage),new{id});}
 [HttpPost] public async Task<IActionResult> UpdateCategory(int id,int eventId,CategoryVm vm){if(!Guard())return Deny();var r=await api.Send("PUT",$"api/categories/{id}",vm);TempData[r.Ok?"Success":"Error"]=r.Ok?"Category updated.":r.Error;return RedirectToAction(nameof(Manage),new{id=eventId});}
 [HttpPost] public async Task<IActionResult> DeleteCategory(int id,int eventId){if(!Guard())return Deny();var r=await api.Send("DELETE",$"api/categories/{id}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Category deleted.":r.Error;return RedirectToAction(nameof(Manage),new{id=eventId});}
 [HttpPost] public async Task<IActionResult> SaveResult(int id,int eventId,TimeSpan? finishTime,int? position,string status="Finished"){if(!Guard())return Deny();var r=await api.Send("POST",$"api/enrolments/{id}/result",new{finishTime,position,status});TempData[r.Ok?"Success":"Error"]=r.Ok?"Result saved.":r.Error;return RedirectToAction(nameof(Manage),new{id=eventId});}
}
